@EventBusSubscriber(modid="around_planet",value=Dist.CLIENT)
public final class RocketClientSmoke {
 private static int ticks,phase;private static boolean busy;private static volatile Throwable failure;private static volatile ServerSubLevel ship;private static volatile PropulsionBlockEntity engine;private static volatile BlockPos plot;private static volatile double initial;private static long started;private static boolean closing;private static volatile boolean passed;
 @SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){var mc=Minecraft.getInstance();mc.options.pauseOnLostFocus=false;if(mc.screen!=null&&mc.screen.getClass().getName().contains("pondus")&&mc.screen.getClass().getSimpleName().contains("Import")){for(var w:mc.screen.children())if(w instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals("Skip")){b.onPress();return;}}if(mc.screen instanceof net.minecraft.client.gui.screens.BackupConfirmScreen){for(var w:mc.screen.children())if(w instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().contains("I know")){b.onPress();return;}}if(++ticks>1800)throw new AssertionError("Rocket client timeout phase="+phase);if(failure!=null)throw new AssertionError("Rocket client",failure);if(mc.player==null||mc.getSingleplayerServer()==null||ticks<120)return;if(phase==0){phase=1;mc.options.renderDistance().set(3);mc.getSingleplayerServer().execute(()->{try{setup(mc);}catch(Throwable t){failure=t;}});return;}
  if(ship==null||engine==null)return;mc.player.setYRot(90);mc.player.setXRot(15);if(ticks%10==0&&!busy){busy=true;mc.getSingleplayerServer().execute(()->{try{var p=ship.getLevel().players().getFirst();var at=ship.logicalPose().position();p.teleportTo(at.x+10,at.y+3,at.z);p.setYRot(90);p.setXRot(15);}catch(Throwable t){failure=t;}finally{busy=false;}});}
  if(phase==1&&mc.level.getBlockEntity(plot) instanceof PropulsionBlockEntity client){if(client.rocket.fuel()<=0||client.actualThrust()<=0)return;io.github.astelev.around_planet.client.PropulsionScreen.open(client);started=ticks;phase=2;return;}
  if(phase==2&&ticks-started>30){if(!(mc.screen instanceof io.github.astelev.around_planet.client.PropulsionScreen))throw new AssertionError("Liquid engine UI did not stay open");net.minecraft.client.Screenshot.grab(mc.gameDirectory,"liquid-rocket-alpha48.png",mc.getMainRenderTarget(),m->{});mc.setScreen(null);phase=3;mc.getSingleplayerServer().execute(()->{try{if(engine.rocket.fuel()>=initial||engine.actualThrust()<=0)throw new AssertionError("Loaded rocket did not consume fuel");if(io.github.astelev.around_planet.client.PropulsionExhaustRenderer.frames==0)throw new AssertionError("Exhaust never rendered");passed=true;AroundPlanet.LOGGER.info("ROCKET_CLIENT_PASS Create tank transfer, own cryogenic fluids, Pondus mass, liquid engine UI and live native exhaust; remaining={} N={}",engine.rocket.fuel(),engine.actualThrust());}catch(Throwable t){failure=t;}});}
  if(phase==3&&passed&&!closing){closing=true;mc.stop();}
 }
 private static void setup(Minecraft mc){var level=mc.getSingleplayerServer().overworld();var p=new BlockPos(30,300,30);level.setBlockAndUpdate(p,PropulsionRegistry.LIQUID.get().defaultBlockState());level.setBlockAndUpdate(p.below(),Blocks.REDSTONE_BLOCK.defaultBlockState());var be=(PropulsionBlockEntity)level.getBlockEntity(p);var input=level.getCapability(Capabilities.FluidHandler.BLOCK,p,null);if(input==null)throw new AssertionError("Engine fluid capability missing");for(int i=0;i<2;i++){var tank=p.offset(4+i*4,0,0);var block=net.minecraft.core.registries.BuiltInRegistries.BLOCK.get(net.minecraft.resources.ResourceLocation.parse("create:fluid_tank"));level.setBlockAndUpdate(tank,block.defaultBlockState());var output=level.getCapability(Capabilities.FluidHandler.BLOCK,tank,null);if(output==null)throw new AssertionError("Create tank capability missing");var fluid=i==0?CryogenicFluids.HYDROGEN.get():CryogenicFluids.OXYGEN.get();output.fill(new FluidStack(fluid,2000),FluidAction.EXECUTE);var moved=FluidUtil.tryFluidTransfer(input,output,new FluidStack(fluid,1000),true);if(moved.getAmount()!=1000)throw new AssertionError("Create transfer failed");}
 var c=SubLevelContainer.getContainer(level);var body=SubLevelAssemblyHelper.assembleBlocks(level,p,List.of(p,p.below()),new BoundingBox3i(30,299,30,30,300,30));body.setName("hydrolox_client_test");c.physicsSystem().getPipeline().teleport(body,new org.joml.Vector3d(12000,6144,0),body.logicalPose().orientation());body.updateBoundingBox();body.updateLastPose();c.physicsSystem().getPipeline().resetVelocity(body);var cell=new io.github.astelev.around_planet.space.SpaceCells.Cell(UUID.randomUUID(),0,12000,6144,0,30,2200,30,List.of(body.getUniqueId()));io.github.astelev.around_planet.space.SpaceCells.get(level).add(level,cell);var data=io.github.astelev.around_planet.space.SpaceOrbitData.get(level.getServer());var planet=new io.github.astelev.around_planet.space.PlanetScale(PlanetConfig.PLANET_SIZE.get()).geometry();double r=planet.radius()+10000,mu=9.81*planet.radius()*planet.radius();data.put(cell.id(),new io.github.astelev.around_planet.space.SpaceTrajectory(io.github.astelev.around_planet.space.CelestialSystem.EARTH,level.getGameTime(),new io.github.astelev.around_planet.space.SpaceState(new io.github.astelev.around_planet.space.SpaceVector(0,r,0),new io.github.astelev.around_planet.space.SpaceVector(Math.sqrt(mu/r),0,0)),mu));data.navigate(cell.id(),new io.github.astelev.around_planet.space.SpaceNavigation(planet,io.github.astelev.around_planet.space.SpaceFrame.IDENTITY));c.addForceLoadTicket(body,dev.ryanhcode.sable.api.sublevel.ticket.SubLevelLoadingTicketType.COMMAND_FORCED,net.minecraft.util.Unit.INSTANCE);ship=body;engine=body.getPlot().getLoadedChunks().stream().flatMap(ch->ch.getChunk().getBlockEntities().values().stream()).filter(PropulsionBlockEntity.class::isInstance).map(PropulsionBlockEntity.class::cast).findFirst().orElseThrow();plot=engine.getBlockPos();initial=engine.rocket.fuel();var player=level.players().getFirst();player.setGameMode(net.minecraft.world.level.GameType.CREATIVE);player.setNoGravity(true);player.teleportTo(12010,6147,0);player.getAbilities().flying=true;player.onUpdateAbilities();}
}
